create extension if not exists "pgcrypto";
create type evidence_level as enum ('verified_jyothi','strong_evidence','moderate_evidence','manufacturer_claim','historical','generic_reference','proposed','unverified','contradicted');
create type application_slug as enum ('horticulture','agriculture','construction','industrial','insulation','other');
create type source_type as enum ('peer_reviewed','standards_body','trade_publication','manufacturer','government','other');
create table industries(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now());
create table applications(id uuid primary key default gen_random_uuid(),slug application_slug not null unique,name text not null,summary text not null,description text not null,examples text[] not null default '{}',evidence_level evidence_level not null default 'generic_reference',evidence_notes text,industry_id uuid references industries(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table products(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,short_description text not null,storage_notes text,safety_notes text,packaging text[] not null default '{}',coa_available boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table product_grades(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,slug text not null unique,name text not null,grade text not null check (grade in ('fine','medium','coarse')),particle_size_min_mm numeric not null,particle_size_max_mm numeric not null,particle_size_evidence_level evidence_level not null default 'generic_reference',target_applications application_slug[] not null default '{}',description text,created_at timestamptz not null default now());
create table technical_properties(id uuid primary key default gen_random_uuid(),product_id uuid references products(id) on delete cascade,name text not null,generic_value text,jyothi_value text,unit text,evidence_level evidence_level not null default 'generic_reference',evidence_source_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table specifications(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,grade_id uuid references product_grades(id) on delete set null,spec_name text not null,spec_value text not null,evidence_level evidence_level not null default 'proposed',created_at timestamptz not null default now());
create table coa_records(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,grade_id uuid references product_grades(id) on delete set null,document_url text not null,issued_date date,lab_name text,is_verified boolean not null default false,created_at timestamptz not null default now());
create table research_sources(id uuid primary key default gen_random_uuid(),title text not null,author text,publication text,year int,url text,source_type source_type not null,created_at timestamptz not null default now());
create table research_claims(id uuid primary key default gen_random_uuid(),claim text not null,application_id uuid references applications(id) on delete set null,evidence_level evidence_level not null default 'generic_reference',source_id uuid references research_sources(id) on delete set null,source_date date,is_jyothi_specific boolean not null default false,is_historical boolean not null default false,is_verified boolean not null default false,notes text,created_at timestamptz not null default now());
create table claim_evidence(id uuid primary key default gen_random_uuid(),claim_id uuid not null references research_claims(id) on delete cascade,source_id uuid not null references research_sources(id) on delete cascade,weight int not null default 1,created_at timestamptz not null default now(),unique(claim_id,source_id));
create table market_prices(id uuid primary key default gen_random_uuid(),product_id uuid references products(id) on delete cascade,grade_id uuid references product_grades(id) on delete set null,price numeric,currency text default 'INR',unit text,is_official_jyothi_quote boolean not null default false,source_note text,recorded_at date not null default current_date,created_at timestamptz not null default now());
create table competitors(id uuid primary key default gen_random_uuid(),name text not null,notes text,created_at timestamptz not null default now());
create table documents(id uuid primary key default gen_random_uuid(),title text not null,category text,file_url text not null,created_at timestamptz not null default now());
create table product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,storage_path text not null,alt_text text not null,sort_order int not null default 0,created_at timestamptz not null default now());
create table certifications(id uuid primary key default gen_random_uuid(),name text not null,issuing_body text,document_url text,is_verified boolean not null default false,created_at timestamptz not null default now());
create table contacts(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text,company text,application application_slug,message text not null,created_at timestamptz not null default now());
alter table industries enable row level security; alter table applications enable row level security; alter table products enable row level security; alter table product_grades enable row level security; alter table technical_properties enable row level security; alter table specifications enable row level security; alter table coa_records enable row level security; alter table research_sources enable row level security; alter table research_claims enable row level security; alter table claim_evidence enable row level security; alter table market_prices enable row level security; alter table competitors enable row level security; alter table documents enable row level security; alter table product_images enable row level security; alter table certifications enable row level security; alter table contacts enable row level security;
do $$ declare t text; begin for t in select unnest(array['industries','applications','products','product_grades','technical_properties','specifications','coa_records','research_sources','research_claims','claim_evidence','market_prices','competitors','documents','product_images','certifications']) loop execute format('create policy "%s_public_read" on %I for select using (true);',t,t); end loop; end $$;
do $$ declare t text; begin for t in select unnest(array['industries','applications','products','product_grades','technical_properties','specifications','coa_records','research_sources','research_claims','claim_evidence','market_prices','competitors','documents','product_images','certifications']) loop execute format('create policy "%s_admin_write" on %I for all using (auth.role() = ''authenticated'') with check (auth.role() = ''authenticated'');',t,t); end loop; end $$;
create policy "contacts_public_insert" on contacts for insert with check(true); create policy "contacts_admin_read" on contacts for select using(auth.role()='authenticated'); create policy "contacts_admin_manage" on contacts for update using(auth.role()='authenticated'); create policy "contacts_admin_delete" on contacts for delete using(auth.role()='authenticated');
create index on applications(slug); create index on products(slug); create index on product_grades(product_id); create index on research_claims(application_id); create index on research_claims(evidence_level); create index on technical_properties(product_id);
